\begin{lemma}\label{lem:stoppedProcess_indicator_sq_norm}
  \lean{ProbabilityTheory.stoppedProcess_indicator_sq_norm}
For any process $M$ and any stopping time $\tau$, stopping the
indicator-truncated squared norm is the same process as taking the squared norm
after indicator-truncating and stopping $M$:
\[
  \left(\|M\|^2 \mathbf{1}_{\{\tau>\bot\}}\right)^\tau_t
  =
  \left\| \left(M\mathbf{1}_{\{\tau>\bot\}}\right)^\tau_t \right\|^2 .
\]
\end{lemma}

\begin{proof}

This is pointwise.  Fix $t$ and $\omega$.  If \(\tau(\omega)=\bot\), both
sides are zero because the indicator vanishes.  If \(\tau(\omega)>\bot\), the
indicator is one and both sides reduce, by the definition of stopped process, to
\(\|M_{t\wedge \tau(\omega)}(\omega)\|^2\).
\end{proof}


\begin{lemma}\label{lem:IsLocalMartingale.isLocalSubmartingale_sq_norm}
  \uses{def:IsLocalMartingale, def:IsLocalSubmartingale, lem:stoppedProcess_indicator_sq_norm}
  \lean{ProbabilityTheory.IsLocalMartingale.isLocalSubmartingale_sq_norm}
If $M$ is a cadlag local martingale, then $\Vert M \Vert^2$ is a cadlag local sub-martingale.
\end{lemma}

\begin{proof}
  \uses{lem:IsSquareIntegrable.submartingale_sq, lem:stoppedProcess_indicator_sq_norm}
Let $(\tau_n)$ be a localizing sequence for the local martingale $M$, so
the stopped and indicator-truncated processes
\[
  M^n_t = M_{t \wedge \tau_n}\mathbf{1}_{\{\tau_n > 0\}}
\]
are càdlàg martingales.  Refine this localization once more so that each
localized process is square integrable: on a deterministic compact time
interval, each càdlàg path is bounded, and the measurable events on which this
pathwise bound is at most a fixed constant increase almost surely to the whole
space.  Intersecting these events with the original localizing sequence and
letting both the deterministic horizon and the bound tend to infinity gives a
new localizing sequence $(\sigma_n)$ such that every
\[
  \widetilde M^n_t
  = M_{t \wedge \sigma_n}\mathbf{1}_{\{\sigma_n > 0\}}
\]
is still a càdlàg martingale and satisfies
\(\sup_t \|\widetilde M^n_t\|_{L^2}<\infty\).

For each $n$, Lemma~\ref{lem:IsSquareIntegrable.submartingale_sq} applied to
\(\widetilde M^n\) shows that
\(\|\widetilde M^n_t\|^2\) is a submartingale.  Stopping commutes with taking
the squared norm, so this submartingale is exactly the process obtained by
stopping and indicator-truncating \(\|M_t\|^2\) at \(\sigma_n\).  Therefore
\((\sigma_n)\) localizes \(\|M\|^2\) as a submartingale.  The càdlàg property
of \(\|M\|^2\) follows by composing the càdlàg paths of \(M\) with the
continuous map \(x \mapsto \|x\|^2\), and stability of càdlàg paths under
stopping gives the local càdlàg component.
\end{proof}


\begin{definition}[Quadratic variation]\label{def:quadraticVariation}
  \uses{def:IsLocalMartingale, thm:local_doobMeyer, lem:IsLocalMartingale.isLocalSubmartingale_sq_norm}
  \lean{ProbabilityTheory.quadraticVariation}
Under the usual normalized Doob--Meyer hypotheses from this section, for $M$ a
càdlàg local martingale, the predictable quadratic variation of $M$ is defined
as the normalized predictable part of the Doob--Meyer decomposition of the
local submartingale $\Vert M \Vert^2$.  We denote it by $\langle M \rangle$.
\end{definition}


\begin{lemma}\label{lem:predictable_quadraticVariation}
  \uses{def:quadraticVariation}
The quadratic variation $\langle M \rangle$ of a local martingale $M$ is a predictable process.
\end{lemma}

\begin{proof}
  \uses{thm:local_doobMeyer}

\end{proof}


\begin{lemma}\label{lem:cadlag_quadraticVariation}
  \uses{def:quadraticVariation}
The quadratic variation $\langle M \rangle$ of a local martingale $M$ is cadlag.
\end{lemma}

\begin{proof}
  \uses{thm:local_doobMeyer}

\end{proof}

